async function sourceFiles(directory = testsRoot) {
  const entries = await fs.readdir(directory, { withFileTypes: true });
  const groups = await Promise.all(
    entries.map(async (entry) => {
      if (['node_modules', 'script-rtws', 'dist'].includes(entry.name)) return [];
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) return sourceFiles(absolute);
      return entry.isFile() && entry.name.endsWith('.ts')
        ? [path.relative(testsRoot, absolute).split(path.sep).join('/')]
        : [];
    }),
  );
  return groups.flat().sort();
}

export async function inventory() {
  const files = await sourceFiles();
  const { scripts } = JSON.parse(await fs.readFile(path.join(testsRoot, 'package.json'), 'utf8'));
  const registrations = Object.entries(scripts).flatMap(([script, command]) =>
    [
      ...command.matchAll(
        /(?:tsx|--)\s+(?:(?:--isolated-rtws|--shared-rtws)\s+)*([\w./-]+\.ts)(?:\s|$)/g,
      ),
    ].map((match) => ({
      script,
      target: match[1],
    })),
  );
  const registered = new Set(registrations.map(({ target }) => target));
  const missingPackageScriptTargets = [];
  for (const registration of registrations) {
    try {
      if (!(await fs.stat(path.resolve(testsRoot, registration.target))).isFile())
        missingPackageScriptTargets.push(registration);
    } catch (error) {
      if (!['ENOENT', 'ENOTDIR'].includes(error.code)) throw error;
      missingPackageScriptTargets.push(registration);
    }
  }
  const support = (file) =>
    file.startsWith('helpers/') ||
    file.startsWith('semantic/') ||
    [
      'cli.ts',
      'rtws-script-runner.ts',
      'kernel-driver/helpers.ts',
      'semantic/evidence.ts',
      'semantic/context-guidance.ts',
    ].includes(file);
  const candidates = files.filter((file) => !support(file));
  const kernel = candidates.filter((file) => file.startsWith('kernel-driver/'));
  const suites = {
    smoke,
    kernel,
    context,
    configuration,
    manual,
    filesystem,
    persistence,
    recovery,
    bootstrap,
    packaging,
    retry,
    projection,
    compatible,
    reminders,
    daemon,
    presentation,
    components,
    shell,
    taskdoc,
    'provider-local': providerLocal,
    'server-local': serverLocal,
    'provider-live': providerLive,
  };
  const included = new Set(Object.values(suites).flat());
  const audit = JSON.parse(await fs.readFile(path.join(testsRoot, 'audit.json'), 'utf8'));
  const unauditedCandidates = candidates.filter((file) => audit.cases[file]?.status !== 'reviewed');
  return {
    typescriptFiles: files.length,
    supportFiles: files.filter(support),
    candidates: candidates.length,
    suites,
    outsideSuites: candidates.filter((file) => !included.has(file)),
    withoutPackageScript: candidates.filter((file) => !registered.has(file)),
    missingPackageScriptTargets,
    unauditedCandidates,
    missingAuditedFiles: Object.keys(audit.cases).filter((file) => !candidates.includes(file)),
    note: 'Discovery and script registration are not measurements of behavior or line coverage. Missing package-script targets cover direct tsx/rtws TypeScript paths, including explicit shared/isolated flags, not arbitrary shell composition. Outside-suite candidates include live probes and external integrations; audit prerequisites before running them.',
  };
}

function killTree(child) {
  if (!child.pid) return;
  if (process.platform === 'win32') {
    const killer = spawn('taskkill', ['/pid', String(child.pid), '/T', '/F'], { stdio: 'ignore' });
    killer.on('error', () => child.kill('SIGKILL'));
  } else {
    try {
      process.kill(-child.pid, 'SIGKILL');
    } catch (error) {
      if (error.code !== 'ESRCH') throw error;
    }
  }
}

export async function runCases(
  cases,
  { logDir, timeoutMs = 60_000, report = console.log, keepSuccessfulState = false },
) {
  await fs.mkdir(logDir, { recursive: true });
  const results = [];
  for (const [index, entry] of cases.entries()) {
    const name = `${String(index + 1).padStart(3, '0')}-${entry.id.replace(/[^\w.-]/g, '_')}`;
    const logPath = path.join(logDir, `${name}.log`);
    // tsx opens a Unix-domain socket under TMPDIR, whose path length is limited.
    const tempDir = path.join(logDir, `${index + 1}.tmp`);
    await fs.mkdir(tempDir);
    const output = await fs.open(logPath, 'w');
    const started = Date.now();
    let timedOut = false;
    const outcome = await new Promise((resolve) => {
      const child = spawn(process.execPath, entry.args, {
        cwd: entry.cwd ?? testsRoot,
        detached: process.platform !== 'win32',
        stdio: ['ignore', output.fd, output.fd],
        env: {
          ...process.env,
          TMPDIR: tempDir,
          TEMP: tempDir,
          TMP: tempDir,
          DOMINDS_TEST_RTWS_KEEP_TMP: '1',
        },
      });
      const timer = setTimeout(() => {
        timedOut = true;
        killTree(child);
      }, timeoutMs);
      child.once('error', (error) => {
        clearTimeout(timer);
        resolve({ error: error.message });
      });
      child.once('close', (code, signal) => {
        clearTimeout(timer);
        resolve({ code, signal });
      });
    });
    await output.close();
    let prerequisite;
    // Only explicitly declared external lanes may use the structured prerequisite protocol.
    // Exit77 by itself remains a failure; no prose is interpreted to infer a skip.
    if (!timedOut && entry.skipExitCode !== undefined && outcome.code === entry.skipExitCode) {
      const records = (await fs.readFile(logPath, 'utf8')).split('\n').flatMap((line) => {
        try {
          const row = JSON.parse(line);
          return row &&
            typeof row === 'object' &&
            row.status === 'skipped' &&
            typeof row.code === 'string' &&
            typeof row.detail === 'string' &&
            row.providerRequestAttempted === false
            ? [row]
            : [];
        } catch {
          return [];
        }
      });
      if (records.length === 1) prerequisite = records[0];
    }
    const status = timedOut
      ? 'timeout'
      : outcome.code === 0
        ? 'passed'
        : prerequisite
          ? 'skipped'
          : 'failed';
    const result = {
      id: entry.id,
      status,
      durationMs: Date.now() - started,
      ...outcome,
      logPath,
      ...(prerequisite ? { prerequisite } : {}),
    };
    if (status === 'passed' && !keepSuccessfulState)
      await fs.rm(tempDir, { recursive: true, force: true });
    else result.tempDir = tempDir;
    results.push(result);
    report(
      `${status.toUpperCase()} ${entry.id} (${result.durationMs}ms)${status === 'passed' ? '' : ` — ${logPath}`}`,
    );
  }
  const summary = {
    total: results.length,
    passed: results.filter((result) => result.status === 'passed').length,
    failed: results.filter((result) => result.status === 'failed').length,
    timedOut: results.filter((result) => result.status === 'timeout').length,
    skipped: results.filter((result) => result.status === 'skipped').length,
    results,
  };
  await fs.writeFile(path.join(logDir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
  return summary;
}

async function main() {
  const args = process.argv.slice(2).filter((arg) => arg !== '--');
  if (args.length === 1 && args[0] === '--list') {
    console.log(JSON.stringify(await inventory(), null, 2));
    return;
  }
  const semantic = args.at(-1) === '--semantic';
  if (semantic) args.pop();
  const liveArgs = args[1] === 'provider-live' ? args.splice(2) : [];
  let selectedLiveCase;
  const caseIndex = liveArgs.indexOf('--case');
  if (caseIndex >= 0) {
    const requested = liveArgs[caseIndex + 1];
    selectedLiveCase = providerLive.find(
      (file) => file === requested || path.basename(file) === requested,
    );
    if (!selectedLiveCase)
      throw new Error('Select a registered live probe with --case <provider/file.ts>');
    liveArgs.splice(caseIndex, 2);
  }
  if (liveArgs.includes('--live') && !selectedLiveCase)
    throw new Error(
      'A live request run requires --case; do not dispatch every provider probe implicitly',
    );
  if (
    args.length !== 2 ||
    args[0] !== '--suite' ||
    ![
      'smoke',
      'kernel',
      'context',
      'configuration',
      'manual',
      'filesystem',
      'persistence',
      'recovery',
      'bootstrap',
      'packaging',
      'retry',
      'projection',
      'compatible',
      'reminders',
      'daemon',
      'presentation',
      'components',
      'shell',
      'taskdoc',
      'provider-local',
      'server-local',
      'provider-live',
    ].includes(args[1])
  ) {
    throw new Error(
      'Usage: node tests/run.mjs --list | --suite smoke | --suite kernel | --suite context [--semantic] | --suite configuration [--semantic] | --suite manual [--semantic] | --suite filesystem [--semantic] | --suite persistence [--semantic] | --suite recovery [--semantic] | --suite bootstrap [--semantic] | --suite packaging [--semantic] | --suite retry [--semantic] | --suite projection [--semantic] | --suite compatible [--semantic] | --suite reminders [--semantic] | --suite daemon [--semantic] | --suite presentation [--semantic] | --suite components [--semantic] | --suite shell [--semantic] | --suite taskdoc [--semantic] | --suite provider-local [--semantic] | --suite server-local [--semantic] | --suite provider-live [--case <provider/file.ts> --live --provider <id> --model <id>]',
    );
  }
  const suite = args[1];
  if (semantic && !Object.hasOwn(semanticSuites, suite)) {
    throw new Error('--semantic requires a suite with explicit evidence producers');
  }
  const files = selectedLiveCase
    ? [selectedLiveCase]
    : semantic
      ? semanticSuites[suite]
      : (await inventory()).suites[suite];
  if (!files.length) throw new Error(`Suite ${suite} discovered no tests`);
  const tsx = require.resolve('tsx/cli');
  const cases = files.map((file) => ({
    id: file,
    ...(suite === 'provider-live' ? { skipExitCode: 77 } : {}),
    args:
      (suite !== 'smoke' && suite !== 'packaging') ||
      persistence.includes(file) ||
      recovery.includes(file) ||
      presentation.includes(file) ||
      configuration.includes(file)
        ? [
            tsx,
            path.join(testsRoot, 'cli.ts'),
            '--',
            file,
            ...liveArgs,
            ...(semantic ? ['--semantic'] : []),
          ]
        : [
            tsx,
            '--tsconfig',
            path.join(testsRoot, 'tsconfig.json'),
            path.join(testsRoot, file),
            ...(semantic ? ['--semantic'] : []),
          ],
  }));
  const logDir = await fs.mkdtemp(
    path.join(os.tmpdir(), `dominds-tests-${suite}${semantic ? '-semantic' : ''}-`),
  );
  console.log(
    `${semantic ? 'Evidence generation processes' : 'Suite'}: ${suite}; cases: ${cases.length}; evidence: ${logDir}`,
  );
  const summary = await runCases(cases, {
    logDir,
    keepSuccessfulState: semantic || suite === 'provider-live',
    report: semantic ? (line) => console.log(`GENERATION PROCESS ${line}`) : console.log,
  });
  if (semantic) {
    await fs.writeFile(
      path.join(logDir, 'summary.json'),
      `${JSON.stringify({ ...summary, scope: 'evidence-generation-processes', semanticAcceptance: 'pending' }, null, 2)}\n`,
    );
    console.log(
      `Generation processes: ${summary.passed} completed, ${summary.failed} failed, ${summary.timedOut} timed out, ${summary.skipped} skipped. Semantic acceptance: PENDING subjective review. Evidence: ${logDir}`,
    );
  } else {
    console.log(
      `Total ${summary.total}: ${summary.passed} passed, ${summary.failed} failed, ${summary.timedOut} timed out, ${summary.skipped} skipped. Evidence: ${logDir}`,
    );
  }
  if (summary.failed || summary.timedOut) process.exitCode = 1;
  else if (summary.skipped) process.exitCode = 2;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import fs from 'node:fs/promises';
import http from 'node:http';
import path from 'node:path';
import YAML from 'yaml';
import { semanticEvidenceCollector } from '../helpers/semantic-evidence';
import { withTempRtws } from '../kernel-driver/helpers';

type Call = { id: string; name: string; args: Record<string, unknown> };
type Wire = { text?: string; calls?: Call[]; thinking?: boolean; invalidSse?: boolean };
function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function jsonLines(text: string): Record<string, unknown>[] {
  return text.split('\n').flatMap((line) => {
    try {
      const value: unknown = JSON.parse(line);
      return record(value) ? [value] : [];
    } catch {
      return [];
    }
  });
}
function completion(model: string, supplied: Wire) {
  const calls = supplied.calls?.map((call) => ({
    id: call.id,
    type: 'function',
    function: { name: call.name, arguments: JSON.stringify(call.args) },
  }));
  return {
    id: 'given-wire-completion',
    object: 'chat.completion',
    created: 1,
    model,
    choices: [
      {
        index: 0,
        finish_reason: calls?.length ? 'tool_calls' : 'stop',
        message: {
          role: 'assistant',
          content: supplied.text ?? 'given-saying-data:1d37',
          ...(supplied.thinking !== false ? { reasoning_content: 'given-thinking-data:65b2' } : {}),
          ...(calls ? { tool_calls: calls } : {}),
        },
      },
    ],
    usage: { prompt_tokens: 1, completion_tokens: 2, total_tokens: 3 },
  };
}
async function main() {
  const evidence = semanticEvidenceCollector('dominds-live-probe-controls-');
  let recorded = false;
  try {
    await withTempRtws(async (rtws) => {
      const artifacts = await fs.mkdtemp(path.join(rtws, 'probe-processes-'));
      let plan: Wire[] = [];
      let requests: Record<string, unknown>[] = [];
      const peerErrors: unknown[] = [];
      const server = http.createServer((request, reply) => {
        const chunks: Buffer[] = [];
        request.on('data', (chunk: Buffer) => chunks.push(chunk));
        request.on('error', (error) => {
          peerErrors.push(error);
          reply.destroy(error);
        });
        request.on('end', () => {
          try {
            const body: unknown = JSON.parse(Buffer.concat(chunks).toString('utf8'));
            assert.ok(record(body));
            assert.equal(request.method, 'POST');
            assert.equal(request.url, '/v1/chat/completions');
            assert.equal(request.headers.authorization === 'Bearer given-local-probe-key', true);
            const response = plan[requests.length];
            requests.push(body);
            console.log(JSON.stringify({ control: 'peer-request', index: requests.length, body }));
            assert.ok(response, 'No unspecified request may be hidden by the controlled peer');
            assert.ok(body.model === 'given-primary' || body.model === 'given-secondary');
            if (body.stream === true) {
              reply.setHeader('content-type', 'text/event-stream');
              if (response.invalidSse) {
                reply.end('data: }\n\ndata: [DONE]\n\n');
                return;
              }
              const base = completion(String(body.model), response);
              const message = base.choices[0]!.message;
              const delta = {
                ...message,
                ...(message.tool_calls
                  ? { tool_calls: message.tool_calls.map((call, index) => ({ index, ...call })) }
                  : {}),
              };
              const chunk = {
                id: base.id,
                object: 'chat.completion.chunk',
                created: 1,
                model: body.model,
                choices: [{ index: 0, delta, finish_reason: null }],
              };
              const finish = {
                ...chunk,
                choices: [{ index: 0, delta: {}, finish_reason: base.choices[0]!.finish_reason }],
                usage: base.usage,
              };
              reply.end(
                'data: ' +
                  JSON.stringify(chunk) +
                  '\n\ndata: ' +
                  JSON.stringify(finish) +
                  '\n\ndata: [DONE]\n\n',
              );
            } else {
              reply.setHeader('content-type', 'application/json');
              reply.end(JSON.stringify(completion(String(body.model), response)));
            }
          } catch (error: unknown) {
            peerErrors.push(error);
            reply.writeHead(500, { 'content-type': 'application/json' });
            reply.end('{"error":{"message":"Controlled peer request fixture failed"}}');
          }
        });
      });
      const listening = once(server, 'listening');
      server.listen(0, '127.0.0.1');
      await listening;
      const address = server.address();
      assert.ok(address && typeof address === 'object');
      const llmYaml = YAML.stringify({
        providers: {
          'given-peer': {
            name: 'Given local peer',
            apiType: 'openai-compatible',
            baseUrl: `http://127.0.0.1:${address.port}/v1`,
            apiKeyEnvVar: 'DOMINDS_TEST_LIVE_PEER_KEY',
            models: {
              'given-primary': { supports_thinking: true },
              'given-secondary': { supports_thinking: true },
            },
          },
          'given-codex-profile': {
            name: 'Given unavailable managed profile',
            apiType: 'codex',
            baseUrl: `http://127.0.0.1:${address.port}/v1`,
            apiKeyEnvVar: 'DOMINDS_TEST_PROBE_AUTH_DIR',
            models: { 'given-primary': {} },
          },
        },
      });
      async function invoke(
        file: string,
        args: string[],
        supplied: Wire[],
        expectedExit: number,
        options: { credential?: boolean; readableProfile?: boolean; semanticId?: string } = {},
      ) {
        plan = supplied;
        requests = [];
        const child = spawn(
          process.execPath,
