            1,
            {},
          ],
          [
            'unknown-provider',
            ['--live', '--provider', 'unconfigured-provider-data', '--model', 'given-primary'],
            1,
            {},
          ],
          ['unknown-option', ['--unconfigured-option'], 1, {}],
          ['missing-option-value', ['--provider'], 1, {}],
          ['unsupported-extra-model', [...live, '--model', 'given-secondary'], 1, {}],
